files.content:
html {
  block-size: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-inline-size: 360px;
  min-block-size: 100%;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 26px;
}

ul {
  margin: 0;
  padding: 0;
}

li {
  font-size: 0.8em;
  display: flex;
  align-items: flex-end;
  list-style-type: none;
}

li img {
  inline-size: 10em;
  block-size: auto;
}
